// Fisher-Yates Shuffle
function shuffle<T>(array: T[]): T[] {
  const arr = [...array];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

// Helper to generate authentic JFT yomikata distractors
function generateJftYomikataDistractors(correctYomi: string, pool: VocabItem[]): string[] {
  const distractors = new Set<string>();

  // 1. Phonetic mutation: Long vowels
  if (correctYomi.includes("ょう")) {
    distractors.add(correctYomi.replace(/ょう/g, "ょ"));
    distractors.add(correctYomi.replace(/ょう/g, "お"));
  }
  if (correctYomi.includes("ゅう")) {
    distractors.add(correctYomi.replace(/ゅう/g, "ゅ"));
  }
  if (correctYomi.includes("おう")) {
    distractors.add(correctYomi.replace(/おう/g, "お"));
    distractors.add(correctYomi.replace(/おう/g, "う"));
  }
  if (correctYomi.includes("とう")) {
    distractors.add(correctYomi.replace(/とう/g, "と"));
  }
  if (correctYomi.includes("こう")) {
    distractors.add(correctYomi.replace(/こう/g, "こ"));
  }

  // 2. Sokuon (っ) mutations
  if (correctYomi.includes("っ")) {
    distractors.add(correctYomi.replace(/っ/g, ""));
  } else if (correctYomi.length >= 3) {
    distractors.add(correctYomi.slice(0, 1) + "っ" + correctYomi.slice(1));
  }

  // 3. Voicing (Dakuten) mutations
  const dakuPairs: [string, string][] = [
    ["か", "が"], ["き", "ぎ"], ["く", "ぐ"], ["け", "げ"], ["こ", "ご"],
    ["さ", "ざ"], ["し", "じ"], ["す", "ず"], ["せ", "ぜ"], ["そ", "ぞ"],
    ["た", "だ"], ["ち", "ぢ"], ["つ", "づ"], ["て", "で"], ["と", "ど"],
    ["は", "ば"], ["ひ", "び"], ["ふ", "ぶ"], ["へ", "べ"], ["ほ", "ぼ"],
    ["は", "ぱ"], ["ひ", "ぴ"], ["ふ", "ぷ"], ["へ", "ぺ"], ["ほ", "ぽ"]
  ];
  for (const [plain, voiced] of dakuPairs) {
    if (correctYomi.includes(plain)) {
      distractors.add(correctYomi.replace(plain, voiced));
    } else if (correctYomi.includes(voiced)) {
      distractors.add(correctYomi.replace(voiced, plain));
    }
  }

  distractors.delete(correctYomi);

  // 4. Fill from authentic pool with similar length
  const similarItems = pool.filter(
    (item) => item.yomi !== correctYomi && Math.abs(item.yomi.length - correctYomi.length) <= 1
  );
  const shuffledSimilar = shuffle(similarItems);
  for (const item of shuffledSimilar) {
    if (distractors.size >= 3) break;
    distractors.add(item.yomi);
  }

  // Fallback to any other yomi
  const fallbackShuffled = shuffle(pool);
  for (const item of fallbackShuffled) {
    if (distractors.size >= 3) break;
    if (item.yomi !== correctYomi) {
      distractors.add(item.yomi);
    }
  }

  return Array.from(distractors).slice(0, 3);
}

// Helper to generate authentic JFT Kanji distractors (when question prompt is Hiragana)
function generateJftKanjiDistractors(targetJa: string, pool: VocabItem[]): string[] {
  const kanjiPool = pool.filter(
    (item) => item.ja !== item.yomi && item.ja !== targetJa && /[\u4e00-\u9faf]/.test(item.ja)
  );
  const similarLength = kanjiPool.filter((item) => Math.abs(item.ja.length - targetJa.length) <= 1);
  const shuffled = shuffle(similarLength.length >= 3 ? similarLength : kanjiPool);
  const selected: string[] = [];
  for (const item of shuffled) {
    if (selected.length >= 3) break;
    if (!selected.includes(item.ja)) {
      selected.push(item.ja);
    }
  }

  while (selected.length < 3) {
    const fallback = pool[Math.floor(Math.random() * pool.length)].ja;
    if (fallback !== targetJa && !selected.includes(fallback)) {
      selected.push(fallback);
    }
  }
  return selected;
}

export function cleanJapaneseText(s: string): string {
  return (s || "")
    .replace(/[\s。、？！\?\!「」\(\)（）\r\n\t]/g, "")
    .trim();
}

interface BunpouItemLite {
  id: string;
  level: string;
  lesson: number;
  pattern: string;
  formulaDetailed?: string;
  meaning: string;
  usageRule?: string;
  example?: string;
  puzzle?: {
    sentence: string;
    translation: string;
    tokens: string[];
    shuffledTokens: string[];
  };
}

const BUNPOU_ITEMS: BunpouItemLite[] = rawBunpouData as unknown as BunpouItemLite[];

function calculateBunpouDifficulty(item: BunpouItemLite): { score: number; tier: "easy" | "medium" | "hard" } {
  const tokenCount = item.puzzle?.tokens?.length || 4;
  const levelWeight = item.level === "a2_2" ? 20 : item.level === "a2_1" ? 10 : 0;
  const lessonWeight = (item.lesson || 1) * 0.5;
  const score = tokenCount * 10 + levelWeight + lessonWeight;

  let tier: "easy" | "medium" | "hard" = "medium";
  if (tokenCount <= 4 && item.level === "a1") {
    tier = "easy";
  } else if (tokenCount >= 7 || item.level === "a2_2") {
    tier = "hard";
  } else {
    tier = "medium";
  }
  return { score, tier };
}

export function generateBunpouPuzzleQuestions(params: {
  level?: VocabLevel;
  chapter?: number;
  count?: number;
}): BattleQuestion[] {
  const { level = "all", chapter = 0, count = 5 } = params;

  const levelMap: Record<string, string> = {
    "A1": "a1",
    "A2.1": "a2_1",
    "A2.2": "a2_2",
  };

  let pool = BUNPOU_ITEMS.filter((item) => {
    if (!item.puzzle || !item.puzzle.sentence) return false;
    if (level !== "all" && item.level !== levelMap[level]) return false;
    if (chapter > 0 && item.lesson !== chapter) return false;
    return true;
  });

  if (pool.length < 4) {
    pool = BUNPOU_ITEMS.filter((item) => !!item.puzzle?.sentence);
  }

  // Calculate difficulty for each pool item
  const poolWithDifficulty = pool.map((item) => ({
    item,
    diff: calculateBunpouDifficulty(item),
  }));

  // Sort pool from easiest to hardest
  poolWithDifficulty.sort((a, b) => a.diff.score - b.diff.score);

  // Group into tiers for progressive selection (termudah hingga tersulit)
  const total = poolWithDifficulty.length;
  let selectedItems: { item: BunpouItemLite; diff: { score: number; tier: "easy" | "medium" | "hard" } }[] = [];

  if (total <= count) {
    // If pool is small, take all and sort
    selectedItems = shuffle(poolWithDifficulty).slice(0, count);
  } else {
    // Split into 3 difficulty tiers
    const tierSize = Math.max(1, Math.floor(total / 3));
    const easyBucket = poolWithDifficulty.slice(0, tierSize);
    const medBucket = poolWithDifficulty.slice(tierSize, tierSize * 2);
    const hardBucket = poolWithDifficulty.slice(tierSize * 2);

    // Progressive quotas based on total count requested
    // e.g. for count=5: 2 easy, 2 medium, 1 hard
    const easyQuota = Math.max(1, Math.floor(count * 0.4));
    const hardQuota = Math.max(1, Math.floor(count * 0.2));
    const medQuota = Math.max(1, count - easyQuota - hardQuota);

    const chosenEasy = shuffle(easyBucket).slice(0, easyQuota);
    const chosenMed = shuffle(medBucket).slice(0, medQuota);
    const chosenHard = shuffle(hardBucket).slice(0, hardQuota);

    const combined = [...chosenEasy, ...chosenMed, ...chosenHard];
    const pickedIds = new Set(combined.map((c) => c.item.id));

    // Fill remaining if quota wasn't met due to small bucket
    if (combined.length < count) {
      const remaining = shuffle(poolWithDifficulty.filter((c) => !pickedIds.has(c.item.id)));
      combined.push(...remaining.slice(0, count - combined.length));
    }

    selectedItems = combined.slice(0, count);
  }

  // Ensure strict ascending progression: Round 1 (easiest) -> Round N (hardest)
  selectedItems.sort((a, b) => a.diff.score - b.diff.score);

  return selectedItems.map(({ item: target, diff }) => {
    const puzzle = target.puzzle!;
    const correctSentence = puzzle.sentence;

    // Distractors from other bunpou items
    const otherSentences = pool
      .filter((i) => i.id !== target.id && i.puzzle?.sentence && i.puzzle.sentence !== correctSentence)
      .map((i) => i.puzzle!.sentence);

    const shuffledOthers = shuffle(otherSentences);
    const chosenDistractors = shuffledOthers.slice(0, 3);

    while (chosenDistractors.length < 3) {
      const fallback = BUNPOU_ITEMS[Math.floor(Math.random() * BUNPOU_ITEMS.length)]?.puzzle?.sentence;
      if (fallback && fallback !== correctSentence && !chosenDistractors.includes(fallback)) {
        chosenDistractors.push(fallback);
      }
    }

    const options = shuffle([correctSentence, ...chosenDistractors]);

    return {
      questionType: "meaning",
      prompt: "Susun Pola Kalimat JFT Sesuai Arti:",
      display: puzzle.translation,
      subDisplay: target.formulaDetailed || target.pattern,
      ja: correctSentence,
      correct: correctSentence,
      options,
      pos: "bunpou_puzzle",
      level: target.level.toUpperCase(),
      chapter: target.lesson,
      puzzleTokens: puzzle.tokens,
      puzzleSentence: correctSentence,
      puzzleTranslation: puzzle.translation,
      pattern: target.pattern,
      formulaDetailed: target.formulaDetailed,
      usageRule: target.usageRule,
      example: target.example,
      difficultyScore: diff.score,
      difficultyTier: diff.tier,
    };
  });
}

export function generateBattleQuestions(params: {
  level?: VocabLevel;
  chapter?: number; // 0 = all
  category?: VocabCategory;
  count?: number;
}): BattleQuestion[] {
  const { level = "all", chapter = 0, category = "all", count = 5 } = params;

  if (category === "bunpou_puzzle") {
    return generateBunpouPuzzleQuestions({ level, chapter, count });
  }

  // 1. Filter pool
  let pool = VOCAB_BANK.filter((item) => {
    if (level !== "all" && item.level !== level) return false;
    if (chapter > 0 && item.chapter !== chapter) return false;
    if (category !== "all" && item.pos !== category) return false;
    return true;
  });

  // Fallback to broader pool if filter is too narrow (< 4 items)
  if (pool.length < 4) {
    pool = VOCAB_BANK.filter((item) => {
      if (category !== "all" && item.pos !== category) return false;
      return true;
    });
  }

  if (pool.length < 4) {
    pool = VOCAB_BANK;
  }

  // 2. Shuffle and pick target items
  const shuffledPool = shuffle(pool);
  const selectedItems = shuffledPool.slice(0, Math.min(count, pool.length));

  // 3. Generate questions in 3 Authentic JFT Types:
  // - kanji_to_yomi: Kanji shown -> 4 Hiragana Yomikata options
  // - hiragana_to_kanji: Hiragana shown -> 4 Kanji options
  // - meaning: Kanji/Kana shown -> 4 Indonesian translation options
  // NO ROMAJI anywhere!
  return selectedItems.map((target, idx) => {
    const hasKanji = target.ja !== target.yomi && /[\u4e00-\u9faf]/.test(target.ja);

    let qType: QuestionType = "meaning";
    if (hasKanji) {
      const typeMod = idx % 3;
      if (typeMod === 0) {
        qType = "kanji_to_yomi";
      } else if (typeMod === 1) {
        qType = "hiragana_to_kanji";
      } else {
        qType = "meaning";
      }
    }

    if (qType === "kanji_to_yomi") {
      const distractors = generateJftYomikataDistractors(target.yomi, VOCAB_BANK);
      const options = shuffle(Array.from(new Set([target.yomi, ...distractors])));
      return {
        questionType: "kanji_to_yomi",
        prompt: "Pilih Cara Baca (Yomikata) Kanji:",
        display: target.ja,
        subDisplay: undefined, // Must NOT show reading because that's the question!
        ja: target.ja,
        yomi: undefined,
        correct: target.yomi,
        options,
        pos: target.pos,
        level: target.level,
        chapter: target.chapter,
      };
    } else if (qType === "hiragana_to_kanji") {
      const distractors = generateJftKanjiDistractors(target.ja, VOCAB_BANK);
      const options = shuffle(Array.from(new Set([target.ja, ...distractors])));
      return {
        questionType: "hiragana_to_kanji",
        prompt: "Pilih Kanji yang Tepat:",
        display: target.yomi,
        subDisplay: undefined,
        ja: target.yomi,
        yomi: undefined,
        correct: target.ja,
        options,
        pos: target.pos,
        level: target.level,
        chapter: target.chapter,
      };
    } else {
      // Type: meaning
      const distractorCandidates = VOCAB_BANK.filter(
        (cand) => cand.arti !== target.arti && (cand.pos === target.pos || cand.level === target.level)
      );

      const shuffledCandidates = shuffle(distractorCandidates.length >= 3 ? distractorCandidates : VOCAB_BANK);
      const chosenDistractors = shuffledCandidates
        .filter((c) => c.arti !== target.arti)
        .slice(0, 3)
        .map((c) => c.arti);

      const uniqueOptions = Array.from(new Set([target.arti, ...chosenDistractors]));
      while (uniqueOptions.length < 4) {
        const fallback = VOCAB_BANK[Math.floor(Math.random() * VOCAB_BANK.length)].arti;
        if (!uniqueOptions.includes(fallback)) {
          uniqueOptions.push(fallback);
        }
      }

      const shuffledOptions = shuffle(uniqueOptions);

      return {
        questionType: "meaning",
        prompt: "Tentukan Arti Bahasa Indonesia:",
        display: target.ja,
        subDisplay: target.ja !== target.yomi ? target.yomi : undefined, // Yomikata only, NEVER ROMAJI!
        ja: target.ja,
        yomi: target.ja !== target.yomi ? target.yomi : undefined,
        correct: target.arti,
        options: shuffledOptions,
        pos: target.pos,
        level: target.level,
        chapter: target.chapter,
      };
    }
  });
}
